package com.tinyclass;

import com.tinyclass.auth.*;
import com.tinyclass.support.ApiBrowser;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.core.env.Environment;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.test.context.ActiveProfiles;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.json.JsonMapper;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties="tinyclass.auth.attempt-limit=1000")
@ActiveProfiles("test")
class DashboardTests {
    static final String TEACHER="dashboard-teacher@example.test",PARENT="dashboard-parent@example.test",OTHER="dashboard-other@example.test",UNVERIFIED="dashboard-unverified@example.test",PASSWORD="Synthetic-dashboard-password-2026";
    static final ZoneId ZONE=ZoneId.of("Asia/Ho_Chi_Minh");
    @Autowired Environment env;@Autowired JdbcTemplate jdbc;@Autowired JsonMapper json;@Autowired UserAccountRepository users;@Autowired PasswordEncoder passwords;
    UUID teacherId,parentId;String classroom,secondClass,child,other,enrollment,secondEnrollment,agreement;
    LocalDate today(){return LocalDate.now(ZONE);}
    @BeforeEach void prepare()throws Exception{
        assertThat(jdbc.queryForObject("select current_database()",String.class)).isEqualTo("tinyclass_test");jdbc.execute("TRUNCATE users,audit_events CASCADE");
        teacherId=users.saveAndFlush(new UserAccount(TEACHER,passwords.encode(PASSWORD),"Dashboard teacher","TEACHER")).getId();parentId=parent(PARENT,true);UUID otherParent=parent(OTHER,true);parent(UNVERIFIED,false);
        try(var t=login(TEACHER)){
            classroom=classroom(t,"Lớp tổng quan");secondClass=classroom(t,"Lớp khác");child=t.post("/students",Map.of("fullName","Bé tổng quan","internalNote","Private child note")).data().path("id").stringValue();other=t.post("/students",Map.of("fullName","Bé khác")).data().path("id").stringValue();
            enrollment=t.post("/classes/"+classroom+"/enrollments",Map.of("studentId",child)).data().path("id").stringValue();secondEnrollment=t.post("/classes/"+secondClass+"/enrollments",Map.of("studentId",other)).data().path("id").stringValue();agreement=agreement(t,enrollment);
        }
        jdbc.update("update class_enrollments set joined_at=?",Timestamp.from(today().minusDays(40).atStartOfDay(ZONE).toInstant()));link(child,parentId);link(other,otherParent);
    }
    UUID parent(String email,boolean verified){var u=new UserAccount(email,passwords.encode(PASSWORD),"Synthetic parent","PARENT");if(verified)u.verifyEmail();return users.saveAndFlush(u).getId();}
    void link(String child,UUID parent){jdbc.update("insert into student_guardians(id,student_id,guardian_user_id,status,linked_at,created_at,updated_at) values(?,?,?,'ACTIVE',now(),now(),now())",UUID.randomUUID(),UUID.fromString(child),parent);}
    ApiBrowser login(String email)throws Exception{var b=new ApiBrowser("http://127.0.0.1:"+env.getProperty("local.server.port"),json);assertThat(b.post("/auth/login",Map.of("email",email,"password",PASSWORD)).status()).isEqualTo(200);return b;}
    String classroom(ApiBrowser t,String name)throws Exception{String c=t.post("/classes",Map.of("name",name,"capacity",5)).data().path("id").stringValue();assertThat(t.post("/classes/"+c+"/activate",Map.of("version",0)).status()).isEqualTo(200);return c;}
    String agreement(ApiBrowser t,String enrollment)throws Exception{var r=t.post("/enrollments/"+enrollment+"/tuition-agreements",Map.of("clientRequestId",UUID.randomUUID(),"source","CUSTOM","terms",Map.of("pricingMode","PER_SESSION","collectionTiming","UPFRONT","sessionUnitPriceVnd",100000,"chargeExcusedAbsence",false,"chargeUnexcusedAbsence",true),"effectiveFrom",today().toString()));assertThat(r.status()).as("%s",r.body()).isEqualTo(201);return r.data().path("id").stringValue();}
    JsonNode invoice(ApiBrowser t,String agreement,long amount,LocalDate due,boolean issue)throws Exception{
        var preview=t.post("/billing/previews",Map.of("agreementId",agreement,"periodStart",today().toString(),"periodEnd",today().toString())).data();var body=new LinkedHashMap<String,Object>();body.put("clientRequestId",UUID.randomUUID());body.put("agreementId",agreement);body.put("periodStart",today().toString());body.put("periodEnd",today().toString());body.put("dueOn",due==null?null:due.toString());body.put("previewKey",preview.path("previewKey").stringValue());body.put("lines",List.of(Map.of("description","Khoản học phí","pricingBasis","OTHER","quantity",1,"unitPriceVnd",amount,"discountVnd",0)));body.put("adjustmentReason","Private invoice reason");
        var r=t.post("/invoices",body);assertThat(r.status()).as("%s",r.body()).isEqualTo(201);var i=r.data();if(issue){r=t.post("/invoices/"+i.path("id").stringValue()+"/issue",Map.of("version",0,"reviewKey",i.path("reviewKey").stringValue()));assertThat(r.status()).isEqualTo(200);i=r.data();}return i;
    }
    JsonNode receive(ApiBrowser t,JsonNode invoice,long amount,Instant paidAt)throws Exception{var r=t.write("POST","/invoices/"+invoice.path("id").stringValue()+"/payments",Map.of("invoiceVersion",invoice.path("version").longValue(),"amountVnd",amount,"method","CASH","paidAt",paidAt.toString(),"internalNote","Private payment note"),true,Map.of("Idempotency-Key",UUID.randomUUID().toString()));assertThat(r.status()).as("%s",r.body()).isEqualTo(201);return r.data();}
    JsonNode teacher(ApiBrowser t)throws Exception{var r=t.get("/dashboard");assertThat(r.status()).as("%s",r.body()).isEqualTo(200);return r.data();}
    JsonNode family(ApiBrowser p)throws Exception{var r=p.get("/family/children/"+child+"/dashboard");assertThat(r.status()).as("%s",r.body()).isEqualTo(200);return r.data();}
    void withdraw(){jdbc.update("update class_enrollments set status='WITHDRAWN',ended_at=now(),status_changed_at=now() where id=?",UUID.fromString(enrollment));jdbc.update("update assignment_recipients set revoked_at=now(),revoke_reason='Synthetic withdrawal' where source_enrollment_id=?",UUID.fromString(enrollment));}
    JsonNode assignment(ApiBrowser t,String mode,boolean future)throws Exception{
        var l=t.post("/lessons",Map.of("title","Hoạt động "+mode,"defaultCompletionMode",mode,"defaultResponseTypes",mode.equals("TEACHER_REVIEW")?List.of("TEXT"):List.of(),"topicIds",List.of(),"blocks",List.of(Map.of("type","TEXT","textContent","Nội dung chia sẻ")))).data();assertThat(t.post("/lessons/"+l.path("id").stringValue()+"/publish",Map.of("version",0)).status()).isEqualTo(200);
        var a=t.post("/assignments",Map.of("title","Lần giao "+mode,"sourceType","LESSON","lessonId",l.path("id").stringValue(),"targetType","CLASS","classId",classroom,"availableAt",Instant.now().plusSeconds(future?3600:-120).toString(),"clientRequestId",UUID.randomUUID())).data();var r=t.post("/assignments/"+a.path("id").stringValue()+"/publish",Map.of("version",0));assertThat(r.status()).as("%s",r.body()).isEqualTo(200);return r.data();
    }
    void announcement(ApiBrowser t)throws Exception{var a=t.post("/announcements",Map.of("clientRequestId",UUID.randomUUID(),"classId",classroom,"title","Bảng tin của bé","body","Nội dung công khai")).data();assertThat(t.post("/announcements/"+a.path("id").stringValue()+"/publish",Map.of("version",0)).status()).isEqualTo(200);}
    @Test void emptyOverviewsUseRealZeroAndNoFakeProgress()throws Exception{
        try(var t=login(TEACHER);var p=login(PARENT)){var b=teacher(t).path("billing");assertThat(b.path("outstandingAmountVnd").stringValue()).isEqualTo("0");assertThat(b.path("receivedThisMonthVnd").stringValue()).isEqualTo("0");assertThat(b.path("dueInvoices").size()).isZero();var f=family(p);assertThat(f.path("learning").path("requiredItems").longValue()).isZero();assertThat(f.path("learning").path("continueAssignment").isNull()).isTrue();assertThat(f.path("recentFeedback").size()).isZero();assertThat(f.path("schedule").path("upcoming").size()).isZero();assertThat(p.get("/family/dashboard").data().path("linkedChildren").longValue()).isEqualTo(1);}
    }
    @Test void collectibleSummaryAndSearchAgreeForPartialZeroDraftCancelAndDueToday()throws Exception{
        try(var t=login(TEACHER)){
            var partial=invoice(t,agreement,800000,today().minusDays(1),true);receive(t,partial,500000,Instant.now().minusSeconds(10));invoice(t,agreement,200000,today(),true);invoice(t,agreement,0,today().minusDays(1),true);invoice(t,agreement,999999,today().minusDays(2),false);var cancelled=invoice(t,agreement,900000,today().minusDays(3),true);t.post("/invoices/"+cancelled.path("id").stringValue()+"/cancel",Map.of("version",1,"reason","Private cancellation"));
            var b=teacher(t).path("billing");assertThat(b.path("openInvoiceCount").longValue()).isEqualTo(2);assertThat(b.path("overdueInvoiceCount").longValue()).isEqualTo(1);assertThat(b.path("outstandingAmountVnd").stringValue()).isEqualTo("500000");assertThat(b.path("dueInvoices").get(0).path("id").stringValue()).isEqualTo(partial.path("id").stringValue());assertThat(t.get("/invoices?collection=OPEN").data().size()).isEqualTo(2);assertThat(t.get("/invoices?collection=OVERDUE").data().size()).isEqualTo(1);assertThat(t.get("/invoices?collection=SETTLED").data().get(0).path("paymentStatus").stringValue()).isEqualTo("NO_PAYMENT_DUE");assertThat(t.get("/invoices?collection=INVALID").status()).isEqualTo(400);
        }
    }
    @Test void receiptsUseVietnamPaidMonthAndExcludeVoidedEntries()throws Exception{
        try(var t=login(TEACHER)){Instant boundary=today().withDayOfMonth(1).atStartOfDay(ZONE).toInstant();var before=invoice(t,agreement,500000,null,true);receive(t,before,400000,boundary.minusSeconds(1));var current=invoice(t,agreement,500000,null,true);var r=receive(t,current,300000,boundary);assertThat(teacher(t).path("billing").path("receivedThisMonthVnd").stringValue()).isEqualTo("300000");var payment=r.path("payment");t.post("/payments/"+payment.path("id").stringValue()+"/void",Map.of("version",0,"invoiceVersion",2,"reason","Private correction"));assertThat(teacher(t).path("billing").path("receivedThisMonthVnd").stringValue()).isEqualTo("0");}
    }
    @Test void teacherClassScopeSeparatesMoneyAndSourceUpdates()throws Exception{
        try(var t=login(TEACHER);var p=login(PARENT)){invoice(t,agreement,800000,today().minusDays(1),true);String another=agreement(t,secondEnrollment);invoice(t,another,900000,null,true);announcement(t);assertThat(teacher(t).path("billing").path("outstandingAmountVnd").stringValue()).isEqualTo("1700000");assertThat(t.get("/dashboard?classId="+classroom).data().path("billing").path("outstandingAmountVnd").stringValue()).isEqualTo("800000");assertThat(t.get("/dashboard?classId="+secondClass).data().path("billing").path("outstandingAmountVnd").stringValue()).isEqualTo("900000");assertThat(family(p).path("billing").path("outstandingAmountVnd").stringValue()).isEqualTo("800000");assertThat(family(p).path("updates").path("unreadCount").longValue()).isEqualTo(2);assertThat(t.get("/dashboard?classId="+UUID.randomUUID()).status()).isEqualTo(404);}
    }
    @Test void aggregateVndAboveJavaScriptSafeIntegerIsAnExactString()throws Exception{
        try(var t=login(TEACHER);var p=login(PARENT)){
            jdbc.update("insert into invoices(id,teacher_id,student_id,class_id,enrollment_id,agreement_id,invoice_code,student_name_snapshot,class_name_snapshot,pricing_mode,terms_snapshot,period_start,period_end,status,total_amount_vnd,adjustment_reason,review_key,client_request_id,request_hash,issued_at) select gen_random_uuid(),?,?,?,?,?,'STRESS-'||g,'Bé tổng quan','Lớp tổng quan','PER_SESSION','{}',?,?,'ISSUED',case when g=9008 then 199254740993 else 1000000000000 end,'Synthetic aggregate test',repeat('a',64),gen_random_uuid(),repeat('b',64),now() from generate_series(1,9008) g",teacherId,UUID.fromString(child),UUID.fromString(classroom),UUID.fromString(enrollment),UUID.fromString(agreement),today(),today());
            jdbc.update("insert into invoice_lines(id,invoice_id,position,description,pricing_basis,quantity,unit_price_vnd,discount_vnd,amount_vnd) select gen_random_uuid(),id,0,'Synthetic aggregate test','OTHER',1,total_amount_vnd,0,total_amount_vnd from invoices");var b=teacher(t).path("billing");assertThat(b.path("outstandingAmountVnd").toString()).isEqualTo("\"9007199254740993\"");assertThat(b.path("dueInvoices").size()).isEqualTo(4);assertThat(family(p).path("billing").path("outstandingAmountVnd").stringValue()).isEqualTo("9007199254740993");
        }
    }
    @Test void familyLearningCountsCurrentOpenRequirementsAndContinuesUnfinishedWork()throws Exception{
        try(var t=login(TEACHER);var p=login(PARENT)){var open=assignment(t,"PARENT_CONFIRM",false);assignment(t,"PARENT_CONFIRM",true);assignment(t,"REFERENCE",false);var learning=family(p).path("learning");assertThat(learning.path("availableAssignments").longValue()).isEqualTo(2);assertThat(learning.path("waitingAssignments").longValue()).isEqualTo(1);assertThat(learning.path("requiredItems").longValue()).isEqualTo(1);assertThat(learning.path("remainingItems").longValue()).isEqualTo(1);assertThat(learning.path("continueAssignment").path("id").stringValue()).isEqualTo(open.path("id").stringValue());String item=open.path("items").get(0).path("id").stringValue();assertThat(p.post("/family/children/"+child+"/assignment-items/"+item+"/confirm",Map.of()).status()).isEqualTo(200);learning=family(p).path("learning");assertThat(learning.path("completedItems").longValue()).isEqualTo(1);assertThat(learning.path("remainingItems").longValue()).isZero();assertThat(learning.path("continueAssignment").isNull()).isTrue();}
    }
    @Test void revisionCountsAreCurrentAndPreviewsAreBounded()throws Exception{
        try(var t=login(TEACHER);var p=login(PARENT)){for(int i=0;i<5;i++)announcement(t);var f=family(p);assertThat(f.path("announcements").path("unreadCount").longValue()).isEqualTo(5);assertThat(f.path("announcements").path("recent").size()).isEqualTo(3);assertThat(f.path("updates").path("recent").size()).isEqualTo(3);String id=f.path("announcements").path("recent").get(0).path("id").stringValue();p.post("/family/children/"+child+"/announcements/"+id+"/read",Map.of("revision",1));assertThat(family(p).path("announcements").path("unreadCount").longValue()).isEqualTo(4);t.put("/announcements/"+id,Map.of("version",1,"title","Updated","body","Public update","reason","Private edit reason"));assertThat(family(p).path("announcements").path("unreadCount").longValue()).isEqualTo(5);}
    }
    @Test void familyHistorySurvivesWithdrawalWhileLearningCalendarAndWallDisappear()throws Exception{
        try(var t=login(TEACHER);var p=login(PARENT)){
            var a=assignment(t,"TEACHER_REVIEW",false);String item=a.path("items").get(0).path("id").stringValue();String id=p.post("/family/children/"+child+"/assignment-items/"+item+"/submissions",Map.of()).data().path("id").stringValue();p.patch("/submissions/"+id,Map.of("version",0,"textResponse","Public work","fileIds",List.of()));p.post("/submissions/"+id+"/submit",Map.of("version",1));assertThat(family(p).path("awaitingReview").longValue()).isEqualTo(1);t.post("/submissions/"+id+"/review",Map.of("version",2,"outcome","ACCEPTED","feedbackText","Shared feedback"));invoice(t,agreement,800000,today().minusDays(1),true);announcement(t);withdraw();var f=family(p);assertThat(f.path("learning").path("availableAssignments").longValue()).isZero();assertThat(f.path("learning").path("requiredItems").longValue()).isZero();assertThat(f.path("announcements").path("unreadCount").longValue()).isZero();assertThat(f.path("billing").path("outstandingAmountVnd").stringValue()).isEqualTo("800000");assertThat(f.path("recentFeedback").size()).isEqualTo(1);assertThat(f.path("awaitingReview").longValue()).isZero();assertThat(f.toString()).doesNotContain("Private","internalNote","requestHash","teacherId","version","feedbackText");
        }
    }
    @Test void archivedChildRetainsHistoryAndGuardianRevokeRemovesDashboard()throws Exception{
        try(var t=login(TEACHER);var p=login(PARENT)){invoice(t,agreement,800000,null,true);assignment(t,"PARENT_CONFIRM",false);announcement(t);jdbc.update("update students set status='ARCHIVED' where id=?",UUID.fromString(child));var f=family(p);assertThat(f.path("billing").path("openInvoiceCount").longValue()).isEqualTo(1);assertThat(f.path("learning").path("recentAssignments").size()).isZero();assertThat(f.path("announcements").path("recent").size()).isZero();jdbc.update("update student_guardians set status='REVOKED' where guardian_user_id=? and student_id=?",parentId,UUID.fromString(child));assertThat(p.get("/family/children/"+child+"/dashboard").status()).isEqualTo(404);assertThat(p.get("/family/dashboard").data().path("linkedChildren").longValue()).isZero();assertThat(p.get("/family/dashboard").data().path("updates").path("unreadCount").longValue()).isZero();}
    }
    @Test void upcomingSessionsFollowCalendarRightsAndExcludeCancelledAndBeyondWindow()throws Exception{
        try(var p=login(PARENT)){var starts=List.of(today().atTime(9,0).atZone(ZONE).toInstant(),today().plusDays(1).atTime(9,0).atZone(ZONE).toInstant(),today().plusDays(2).atTime(9,0).atZone(ZONE).toInstant(),today().plusDays(3).atTime(9,0).atZone(ZONE).toInstant(),today().plusDays(4).atTime(9,0).atZone(ZONE).toInstant(),today().plusDays(8).atStartOfDay(ZONE).toInstant());for(var start:starts)jdbc.update("insert into class_sessions(id,class_id,title,starts_at,ends_at) values(?,?,'Public session',?,?)",UUID.randomUUID(),UUID.fromString(classroom),Timestamp.from(start),Timestamp.from(start.plusSeconds(3600)));var f=family(p);assertThat(f.path("schedule").path("todaySessionCount").longValue()).isEqualTo(1);assertThat(f.path("schedule").path("upcoming").size()).isEqualTo(3);for(var row:f.path("schedule").path("upcoming"))assertThat(Instant.parse(row.path("startsAt").stringValue())).isAfterOrEqualTo(Instant.now().minusSeconds(2));jdbc.update("update class_sessions set status='CANCELLED',cancelled_at=now(),cancellation_reason='Public cancellation' where (starts_at at time zone 'Asia/Ho_Chi_Minh')::date=?",today());assertThat(family(p).path("schedule").path("todaySessionCount").longValue()).isZero();withdraw();assertThat(family(p).path("schedule").path("upcoming").size()).isZero();}
    }
    @Test void rolesEmailAndChildScopeProtectAllAggregates()throws Exception{
        try(var t=login(TEACHER);var p=login(PARENT);var o=login(OTHER);var u=login(UNVERIFIED);var anonymous=new ApiBrowser("http://127.0.0.1:"+env.getProperty("local.server.port"),json)){assertThat(t.get("/family/dashboard").status()).isEqualTo(403);assertThat(p.get("/dashboard").status()).isEqualTo(403);assertThat(u.get("/family/dashboard").status()).isEqualTo(403);assertThat(u.get("/family/children/"+child+"/dashboard").status()).isEqualTo(403);assertThat(o.get("/family/children/"+child+"/dashboard").status()).isEqualTo(404);assertThat(p.get("/family/children/"+other+"/dashboard").status()).isEqualTo(404);assertThat(anonymous.get("/family/dashboard").status()).isEqualTo(401);}
    }
    @Test void completedOrArchivedClassesKeepFeesAndRemoveActionableLearning()throws Exception{
        try(var t=login(TEACHER);var p=login(PARENT)){invoice(t,agreement,800000,null,true);assignment(t,"PARENT_CONFIRM",false);jdbc.update("update classes set status='COMPLETED' where id=?",UUID.fromString(classroom));jdbc.update("update class_enrollments set status='COMPLETED',ended_at=now() where id=?",UUID.fromString(enrollment));var f=family(p);assertThat(f.path("learning").path("availableAssignments").longValue()).isEqualTo(1);assertThat(f.path("learning").path("requiredItems").longValue()).isZero();assertThat(f.path("learning").path("continueAssignment").isNull()).isTrue();jdbc.update("update classes set status='ARCHIVED' where id=?",UUID.fromString(classroom));assertThat(family(p).path("learning").path("availableAssignments").longValue()).isZero();assertThat(t.get("/dashboard?classId="+classroom).data().path("billing").path("outstandingAmountVnd").stringValue()).isEqualTo("800000");}
    }
}
